package com.ems.util;
import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import java.util.regex.Pattern;
public final class InputValidator { private static final Pattern EMAIL=Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"); private InputValidator(){}
 public static Map<String,String> employee(String name,String email,String phone,String dept,String designation,String salary,String date,String status){ Map<String,String> e=new LinkedHashMap<>(); if(blank(name))e.put("fullName","Full name is required."); if(blank(email)||!EMAIL.matcher(email.trim()).matches())e.put("email","Enter a valid email address."); if(blank(phone))e.put("phone","Phone is required."); if(blank(dept))e.put("department","Department is required."); if(blank(designation))e.put("designation","Designation is required."); try{if(blank(salary)||new BigDecimal(salary).signum()<0)e.put("salary","Salary must be a non-negative number.");}catch(Exception x){e.put("salary","Salary must be a valid number.");} try{if(blank(date))e.put("joiningDate","Joining date is required.");else LocalDate.parse(date);}catch(Exception x){e.put("joiningDate","Joining date is invalid.");} if(!List.of("Active","On Leave","Inactive").contains(status))e.put("employmentStatus","Choose a valid employment status."); return e; }
 public static boolean blank(String s){return s==null||s.trim().isEmpty();}
}
